-- GENERATED by database/scripts/build_dist.sh. Do not edit by hand.
-- Run AFTER 01_create_schema.sql. Hardcoded IDs assume freshly created tables.

USE bizkit;
GO

-- Guard: refuse to run against tables that already hold data, since
-- the hardcoded IDs would collide. SET NOEXEC ON skips every remaining
-- batch; it's switched back off at the end.
IF EXISTS (SELECT 1 FROM dbo.SERVICE_AREA)
BEGIN
    RAISERROR('Tables already contain data. Run 01_create_schema.sql first, then rerun this script.', 16, 1);
    SET NOEXEC ON;
END
GO

